SELECT CASE WHEN budget >= 4117000 THEN 'high' WHEN budget >= 1150000 THEN 'mid' ELSE 'low' END AS budget_bucket, location, COUNT(CASE WHEN location = 'Chiang Mai' THEN 1 END) AS chiang_mai_count, COUNT(budget) AS budget_count, SUM(budget) AS total_budget FROM departments WHERE budget < 1839000 OR location IN ('London', 'New York', 'Chiang Mai') GROUP BY 1, 2 HAVING COUNT(CASE WHEN location = 'Chiang Mai' THEN 1 END) >= 1
